    }
    __syncthreads();

    float inv_std_div = s_inv_std;

    // Normalize and divide
    for (int i = threadIdx.x; i < HW; i += blockDim.x) {
        out_ptr[i] = (in_ptr[i] - mean) * inv_std_div;
