    for (int i = threadIdx.x; i < vec_HW; i += blockDim.x) {
        float4 vals = in_vec[i];
        local_sum += vals.x + vals.y + vals.z + vals.w;
        local_sum_sq += vals.x * vals.x + vals.y * vals.y + vals.z * vals.z + vals.w * vals.w;
