        result.w = (vals.w - mean) * inv_std_div;
        out_vec[i] = result;
    }

    // Handle remaining elements
    for (int i = vec_HW * 4 + threadIdx.x; i < HW; i += blockDim.x) {
        out_ptr[i] = (in_ptr[i] - mean) * inv_std_div;
    }
