__device__ __forceinline__ void warpReduceSumTwo(float& v1, float& v2) {
    #pragma unroll
    for (int offset = 32; offset > 0; offset /= 2) {
        v1 += __shfl_down(v1, offset);
        v2 += __shfl_down(v2, offset);
    }
